{% extends "regions/base_public.html" %}
{% load static %}
{% load region_extras %}

{% block extra_js %}
<script>
// Analytics beacon - runs on every page load (even cached pages)
(function() {
    var beacon = new Image();
    beacon.src = '{% url "regions:track_view" slug=region.slug %}?stage=REGION_VIEW&_=' + Date.now();
})();
</script>
{% endblock %}

{% block structured_data %}
{% include "regions/partials/_structured_data.html" with region=region events=events description=page_meta.meta_description %}
{% endblock %}

{% block content %}
<div class="region-page">
    {# Hero Section #}
    <section class="region-hero" style="--hero-image: url('{{ region.hero_image_url|default:"https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600" }}');">
        <div class="region-hero__overlay"></div>
        <div class="region-hero__content">
            <nav class="region-breadcrumb">
                <a href="{% url 'regions:explore' %}">Explore</a>
                <span class="separator">/</span>
                <span class="current">{{ region.name }}</span>
            </nav>
            <h1 class="region-hero__title">{{ region.tagline|default:region.name }}</h1>
            <p class="region-hero__subtitle">{{ total_events }} upcoming events</p>
            <div class="region-hero__cta">
                <a href="{{ region.get_specials_today_url }}" class="btn btn-outline-light btn-lg">
                    Today's Specials
                </a>
                <a href="{% url 'account_signup' %}?region={{ region.id }}" class="btn btn-primary btn-lg">
                    Plan a Trip
                </a>
            </div>
        </div>
    </section>

    {# Region Description #}
    {% if region.description %}
    <section class="region-about">
        <div class="container">
            <div class="row justify-content-center">
                <div class="col-lg-8">
                    <div class="about-content">
                        <h2>About {{ region.name }}</h2>
                        <p>{{ region.description }}</p>
                    </div>
                </div>
            </div>
        </div>
    </section>
    {% endif %}

    {# Filters #}
    <section class="events-filters">

