    min-height: 320px;
    height: 42vh;
    max-height: 520px;
    border-top: 1px solid rgba(69, 183, 209, 0.12);
}

.specials-map .leaflet-popup-content-wrapper {
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
}

.specials-map-popup__venue {
    font-family: var(--font-display);
    font-size: 1.15rem;
    color: var(--color-gray-900);
    margin-bottom: var(--space-2);
}

.specials-map-popup__address {
    color: var(--color-gray-500);
    font-size: 0.9rem;
    margin-bottom: var(--space-3);
}

.specials-map-popup__list {
    margin: 0 0 var(--space-3);
    padding-left: 1rem;
    color: var(--color-gray-700);
}

.specials-map-popup__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
}

.specials-map-popup__focus,
.specials-map-popup__link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.55rem 0.9rem;
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 700;
    text-decoration: none;
}

.specials-map-popup__focus {
    border: none;
    background: var(--color-ocean);
    color: var(--color-white);
}

.specials-map-popup__link {
    background: rgba(69, 183, 209, 0.1);
    color: var(--color-ocean-dark);
}

.specials-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-6);
}

.special-card {
    background: var(--color-white);
    border: 1px solid rgba(69, 183, 209, 0.14);
    border-radius: var(--radius-2xl);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
    display: flex;
    flex-direction: column;
    transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.special-card--map-active {
    border-color: rgba(255, 107, 107, 0.5);
    box-shadow: 0 24px 48px -24px rgba(255, 107, 107, 0.45), var(--shadow-xl);
    transform: translateY(-2px);
}

.special-card--map-flash {
    animation: special-card-map-flash 1.45s ease-out;
}

@keyframes special-card-map-flash {
    0% {
        border-color: rgba(255, 107, 107, 0.32);
        box-shadow: 0 0 0 0 rgba(255, 107, 107, 0.12), var(--shadow-xl);
        transform: translateY(-2px) scale(1);
    }
    18% {
        border-color: rgba(255, 107, 107, 0.95);
        box-shadow:
            0 0 0 8px rgba(255, 107, 107, 0.14),
            0 26px 56px -24px rgba(255, 107, 107, 0.52),
            var(--shadow-xl);
        transform: translateY(-4px) scale(1.012);
    }
    48% {
        border-color: rgba(255, 107, 107, 0.84);
        box-shadow:
            0 0 0 12px rgba(255, 107, 107, 0.08),
            0 26px 56px -24px rgba(255, 107, 107, 0.48),
            var(--shadow-xl);
        transform: translateY(-3px) scale(1.008);
    }
    100% {
        border-color: rgba(255, 107, 107, 0.5);
        box-shadow: 0 24px 48px -24px rgba(255, 107, 107, 0.45), var(--shadow-xl);
        transform: translateY(-2px) scale(1);
    }
}

.special-card__media {
    min-height: 130px;
    background:
        radial-gradient(circle at top left, rgba(255, 255, 255, 0.6), transparent 35%),
        linear-gradient(135deg, rgba(255, 107, 107, 0.18), rgba(69, 183, 209, 0.65));
    padding: var(--space-5);
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.special-card__media--image {
    background-position: center;
    background-size: cover;
}

.special-card__badge,
.special-card__recurring {
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-3);
}

.special-card__badge {
    background: rgba(255, 255, 255, 0.92);
    color: var(--color-driftwood);
}

.special-card__badge--meal,
.special-card__badge--time {
    background: rgba(240, 249, 255, 0.92);
    color: var(--color-ocean-dark);
    border: 1px solid rgba(125, 211, 252, 0.42);
}

.special-card__recurring {
    background: rgba(17, 24, 39, 0.72);
    color: var(--color-white);
}

.special-card__body {
    padding: var(--space-6);
}

.special-card__header {
    display: flex;
    justify-content: space-between;
    gap: var(--space-4);
    margin-bottom: var(--space-4);
}

.special-card__title {
    font-size: 1.5rem;
    margin-bottom: var(--space-2);
}

.special-card__location,
.special-card__address {
    color: var(--color-gray-600);
}

.special-card__location {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 600;
}

.special-card__address {
    margin-top: var(--space-2);
    font-size: 0.95rem;
}

.special-card__time {
    white-space: nowrap;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--color-ocean-dark);
    background: rgba(69, 183, 209, 0.12);
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-3);
    align-self: flex-start;
}

.special-card__lede {
    color: var(--color-gray-700);
    margin-bottom: var(--space-4);
}

.special-card__menu {
    list-style: none;
    padding: 0;
    margin: 0 0 var(--space-5);
    display: grid;
    gap: var(--space-3);
}

.special-card__menu li {
    position: relative;
    padding: var(--space-3) var(--space-4) var(--space-3) 2rem;
    color: var(--color-gray-800);
    border-radius: var(--radius-lg);
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid rgba(154, 52, 18, 0.08);
    min-height: 100%;
}

.special-card__menu li::before {
    content: "•";
    position: absolute;
    left: 0.85rem;
    top: 0.9rem;
    color: var(--color-sunset);
    font-size: 1.2rem;
    line-height: 1;
}

.special-card__menu-more {
    margin-top: calc(var(--space-4) * -1);
    margin-bottom: var(--space-5);
    color: var(--color-gray-600);
    font-weight: 600;
}

.special-card__promo-list {
    list-style: none;
    padding: 0;
    margin: calc(var(--space-4) * -1) 0 var(--space-5);
    display: grid;
    gap: var(--space-2);
}

.special-card__promo-item {
    position: relative;
    padding-left: 1.35rem;
    color: var(--color-gray-600);
    font-size: 0.95rem;
    line-height: 1.5;
}

.special-card__promo-item::before {
    content: "•";
    position: absolute;
    left: 0.25rem;
    top: 0.05rem;
    color: rgba(14, 116, 144, 0.68);
    font-size: 1rem;
    line-height: 1;
}

.special-card__copy {
    color: var(--color-gray-700);
    margin-bottom: var(--space-5);
}

.special-card__copy p:last-child {
    margin-bottom: 0;
}

.special-card__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
    margin-top: var(--space-5);
}

.specials-empty-state {
    padding: var(--space-16) var(--space-8);
}

@media (max-width: 768px) {
    .explore-hero__content,
    .specials-hero__content {
        padding: var(--space-8) var(--space-4);
    }

    .specials-topbar__inner {
        flex-direction: column;
        text-align: center;
        gap: var(--space-2);
        padding: 0 var(--space-4);
    }

    .specials-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .special-card__header {
        flex-direction: column;
    }

    .specials-map {
        height: 320px;
    }
}

@media (min-width: 992px) {
    .specials-layout--with-map {
        grid-template-columns: minmax(340px, 420px) minmax(0, 1fr);
        align-items: start;
    }

    .specials-map-panel {
        position: sticky;
        top: calc(88px + var(--space-4));
    }
}


/* ============================================
   Section Styles
   ============================================ */
section {
    padding: var(--space-12) 0;
}

.section-title {
    font-family: var(--font-display);
    font-size: 2rem;
    font-weight: 600;
    margin-bottom: var(--space-6);
    color: var(--color-gray-900);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-6);
}

.view-all-link {
    font-weight: 500;
    color: var(--color-ocean);
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: var(--space-2);
}

.view-all-link:hover {
    color: var(--color-ocean-dark);
}

/* Featured Regions */
.featured-regions {
    background: var(--color-gray-50);
}

/* All Regions */
.all-regions {
    background: var(--color-white);
}


/* ============================================
   Region Cards
   ============================================ */
.region-card {
    display: block;
    text-decoration: none;
    color: inherit;
    background: var(--color-white);
    border-radius: var(--radius-xl);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

.region-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);
    color: inherit;
    text-decoration: none;
}

.region-card__image {
    height: 200px;
    background-size: cover;
    background-position: center;
    position: relative;
}

.region-card__image--small {
    height: 140px;
}

.region-card__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.3) 100%);
}

.region-card__badge {
    position: absolute;
    top: var(--space-3);
    left: var(--space-3);
    background: var(--color-ocean);
    color: var(--color-white);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-1) var(--space-3);
    border-radius: var(--radius-full);
}

.region-card__content {
    padding: var(--space-4);
}

.region-card__title {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: var(--space-2);
    color: var(--color-gray-900);
}

.region-card__tagline {
    font-size: 0.875rem;
    color: var(--color-gray-600);
    margin-bottom: var(--space-3);
    line-height: 1.5;
}

.region-card__meta {
    font-size: 0.875rem;
    color: var(--color-gray-500);
}

.region-card__events {
    display: flex;
    align-items: center;
    gap: var(--space-2);
}


/* ============================================
   Event Cards
   ============================================ */
.event-card {
    background: var(--color-white);
    border-radius: var(--radius-lg);
    border: 1px solid var(--color-gray-200);
    overflow: hidden;
    position: relative;
    transition: transform var(--transition-normal), box-shadow var(--transition-normal), border-color var(--transition-normal);
}

.event-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    border-color: var(--color-ocean-light);
}

.event-card__link {
    display: block;
    padding: var(--space-4);
    text-decoration: none;
    color: inherit;
}

.event-card__link:hover {
    color: inherit;
    text-decoration: none;
}

.event-card__category {
    display: inline-block;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-sm);
    margin-bottom: var(--space-2);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
}

/* Category Colors */
.event-card__category--event { background: #dbeafe; color: #1e40af; }
.event-card__category--food { background: #ffedd5; color: #9a3412; }

/* Recurring Badge - shows "Weekly", "Daily", etc. */
.event-card__recurring-badge {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    padding: 2px 6px;
    border-radius: var(--radius-sm);
    margin-left: var(--space-2);
    background: var(--color-gray-100);
    color: var(--color-gray-500);
    vertical-align: middle;
}

.event-card__content {
    min-height: 80px;
}

.event-card__title {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--space-2);
    color: var(--color-gray-900);
    line-height: 1.3;
}

.event-card__meta {
    display: flex;
    gap: var(--space-4);
    font-size: 0.875rem;
    color: var(--color-gray-500);
    margin-bottom: var(--space-2);
}

.event-card__date,
.event-card__time {
    display: flex;
    align-items: center;
    gap: var(--space-1);
}

.event-card__location {
    font-size: 0.875rem;
    color: var(--color-gray-500);
    display: flex;
    align-items: center;
    gap: var(--space-1);
}

/* Save Button */
.event-card__save-btn {
    position: absolute;
    top: var(--space-3);
    right: var(--space-3);
    width: 36px;
    height: 36px;
    border: none;
    border-radius: var(--radius-full);
    background: var(--color-white);
    color: var(--color-gray-400);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-fast);
}

.event-card__save-btn:hover {
    color: var(--color-ocean);
    transform: scale(1.1);
}

.event-card__save-btn.saved {
    background: var(--color-ocean);
    color: var(--color-white);
}


/* ============================================
   Category Filters
   ============================================ */
.category-filters {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
    padding: var(--space-4) 0;
}

.category-filter {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
    font-size: 0.875rem;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: all var(--transition-fast);
    border: 2px solid transparent;
}

.category-filter:hover {
    background: var(--color-gray-200);
    color: var(--color-gray-700);
    text-decoration: none;
}

.category-filter.active {
    background: var(--color-ocean);
    color: var(--color-white);
    border-color: var(--color-ocean);
}


/* ============================================
   Event Detail Page
   ============================================ */
.event-detail-page {
    padding-bottom: var(--space-16);
}

.event-detail-card {
    background: var(--color-white);
    border-radius: var(--radius-xl);
    padding: var(--space-6);
    box-shadow: var(--shadow-lg);
    margin-top: var(--space-6);
    overflow: hidden;
}

.event-category-badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-bottom: var(--space-4);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
}

/* Category badge colors */
.event-category-badge--festival { background: #fef3c7; color: #92400e; }
.event-category-badge--concert { background: #fce7f3; color: #9d174d; }
.event-category-badge--market { background: #d1fae5; color: #065f46; }
.event-category-badge--community { background: #dbeafe; color: #1e40af; }
.event-category-badge--nature { background: #dcfce7; color: #166534; }
.event-category-badge--sports { background: #fee2e2; color: #991b1b; }
.event-category-badge--food { background: #ffedd5; color: #9a3412; }

.event-meal-period-badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-left: var(--space-2);
    margin-bottom: var(--space-4);
    background: rgba(186, 230, 253, 0.24);
    color: inherit;
    border: 1px solid rgba(255, 255, 255, 0.18);
}

.event-detail__hero {
    margin: calc(-1 * var(--space-6));
    margin-bottom: var(--space-6);
    padding: var(--space-8);
    border-radius: var(--radius-xl);
    position: relative;
    overflow: hidden;
    background-size: cover;
    background-position: center;
}

.event-detail__hero--fallback {
    background:
        radial-gradient(circle at top right, rgba(255,255,255,0.25), transparent 32%),
        linear-gradient(135deg, #10324a 0%, #1d5c7f 54%, #d97706 100%);
    color: var(--color-white);
}

.event-detail__hero--fallback.event-detail__hero--food {
    background:
        radial-gradient(circle at top right, rgba(255,248,235,0.38), transparent 30%),
        linear-gradient(135deg, #7c2d12 0%, #c2410c 52%, #f59e0b 100%);
}

.event-detail__hero--image {
    color: var(--color-white);
    min-height: 320px;
    display: flex;
    align-items: end;
}

.event-detail__hero-copy {
    max-width: 42rem;
    position: relative;
    z-index: 1;
}

.event-detail__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: var(--space-3);
    opacity: 0.92;
}

.event-detail__title {
    font-family: var(--font-display);
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: var(--space-4);
    color: var(--color-gray-900);
}

.event-detail__hero .event-detail__title {
    color: inherit;
    margin-bottom: var(--space-3);
}

.event-detail__lede {
    margin: 0;
    font-size: 1.05rem;
    line-height: 1.75;
    max-width: 38rem;
    color: inherit;
    opacity: 0.96;
}

.event-detail__datetime,
.event-detail__location {
    display: flex;
    gap: var(--space-4);
    margin-bottom: var(--space-4);
    padding: var(--space-4);
    background: var(--color-gray-50);
    border-radius: var(--radius-lg);
}

.event-detail__datetime i,
.event-detail__location i {
    font-size: 1.5rem;
    color: var(--color-ocean);
}

.event-date {
    font-weight: 600;
    color: var(--color-gray-900);
}

.event-time {
    color: var(--color-gray-600);
}

.location-name {
    font-weight: 600;
    color: var(--color-gray-900);
}

.location-address {
    color: var(--color-gray-600);
}

.event-detail__description {
    margin: var(--space-6) 0;
    color: var(--color-gray-700);
    line-height: 1.8;
}

.event-detail__place-card {
    margin: var(--space-6) 0;
    padding: var(--space-6);
    border-radius: var(--radius-xl);
    background:
        linear-gradient(180deg, rgba(248, 250, 252, 0.92), rgba(255,255,255,0.98)),
        linear-gradient(135deg, rgba(219, 234, 254, 0.7), rgba(240, 249, 255, 0.85));
    border: 1px solid rgba(37, 99, 235, 0.12);
}

.event-detail__place-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: var(--space-3);
}

.event-detail__place-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-3);
    padding: var(--space-4);
    border-radius: var(--radius-lg);
    text-decoration: none;
    color: var(--color-gray-800);
    background: rgba(255,255,255,0.92);
    border: 1px solid rgba(59, 130, 246, 0.12);
    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.event-detail__place-link:hover {
    color: var(--color-ocean-dark);
    text-decoration: none;
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

.event-detail__rating {
    margin-top: var(--space-4);
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 600;
    color: var(--color-gray-900);
}

.event-detail__rating i {
    color: #f59e0b;
}

.event-detail__rating-count {
    color: var(--color-gray-600);
    font-weight: 500;
}

.event-detail__hours {
    margin-top: var(--space-5);
}

.event-detail__hours-label {
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-gray-500);
    margin-bottom: var(--space-2);
}

.event-detail__hours-pills {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
}

.event-detail__hours-pill {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: rgba(255,255,255,0.92);
    border: 1px solid rgba(15, 23, 42, 0.08);
    color: var(--color-gray-700);
    line-height: 1.2;
}

.event-detail__hours-pill--current {
    background: rgba(69, 183, 209, 0.12);
    border-color: rgba(58, 163, 189, 0.28);
    color: var(--color-ocean-dark);
}

.event-detail__hours-day {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.4rem;
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-full);
    background: rgba(15, 23, 42, 0.06);
    color: var(--color-gray-600);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.event-detail__hours-pill--current .event-detail__hours-day {
    background: rgba(69, 183, 209, 0.18);
    color: var(--color-ocean-dark);
}

.event-detail__hours-value {
    font-size: 0.92rem;
    font-weight: 600;
}

.event-detail__hours-mobile {
    display: none;
    margin-top: var(--space-2);
}

.event-detail__hours-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-3);
    cursor: pointer;
    list-style: none;
}

.event-detail__hours-toggle::-webkit-details-marker {
    display: none;
}

.event-detail__hours-toggle-text {
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--color-ocean-dark);
}

.event-detail__hours-toggle-label--open,
.event-detail__hours-mobile[open] .event-detail__hours-toggle-label--closed {
    display: none;
}

.event-detail__hours-mobile[open] .event-detail__hours-toggle-label--open {
    display: inline;
}

.event-detail__hours-pills--mobile-expanded {
    margin-top: var(--space-2);
}

.event-detail__description p:last-child {
    margin-bottom: 0;
}

.event-detail__menu-board {
    margin: var(--space-6) 0;
    padding: var(--space-6);
    border-radius: var(--radius-xl);
    background:
        linear-gradient(180deg, rgba(255,255,255,0.7), rgba(255,255,255,0.96)),
        linear-gradient(135deg, rgba(255,237,213,0.8), rgba(255,251,235,0.85));
    border: 1px solid rgba(249, 115, 22, 0.16);
}

.event-detail__section-label {
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-gray-500);
    margin-bottom: var(--space-4);
}

.event-detail__menu-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: var(--space-3);
}

.event-detail__menu-item {
    display: flex;
    align-items: start;
    gap: var(--space-3);
    padding: var(--space-4);
    border-radius: var(--radius-lg);
    background: rgba(255,255,255,0.85);
    border: 1px solid rgba(154, 52, 18, 0.08);
    color: var(--color-gray-800);
    font-weight: 500;
    min-height: 100%;
}

.event-detail__menu-item-icon {
    width: 2rem;
    height: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: rgba(245, 158, 11, 0.16);
    color: #b45309;
    flex: 0 0 auto;
}

.event-detail__promo-list {
    list-style: none;
    padding: 0;
    margin: calc(var(--space-5) * -1) 0 var(--space-6);
    display: grid;
    gap: var(--space-3);
}

.event-detail__promo-item {
    display: flex;
    align-items: start;
    gap: var(--space-3);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-lg);
    background: rgba(248, 250, 252, 0.88);
    border: 1px solid rgba(148, 163, 184, 0.24);
    color: var(--color-gray-700);
    font-size: 0.97rem;
}

.event-detail__promo-item-icon {
    width: 1.75rem;
    height: 1.75rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: rgba(14, 116, 144, 0.1);
    color: rgba(14, 116, 144, 0.85);
    flex: 0 0 auto;
}

.event-detail__external-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    color: var(--color-ocean);
    font-weight: 500;
    text-decoration: none;
    margin-bottom: var(--space-6);
}

.event-detail__external-link:hover {
    text-decoration: underline;
}

.event-detail__actions {
    display: flex;
    gap: var(--space-3);
    flex-wrap: wrap;
    padding-top: var(--space-6);
    border-top: 1px solid var(--color-gray-200);
}

.btn-save-event {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
}

.btn-save-event.saved {
    background: var(--color-ocean);
    border-color: var(--color-ocean);
    color: var(--color-white);
}

.share-buttons {
    margin-left: auto;
}

.back-to-events {
    margin-top: var(--space-8);
    text-align: center;
}


/* ============================================
   Events Page Header
   ============================================ */
.events-header {
    background: linear-gradient(135deg, var(--color-ocean) 0%, var(--color-driftwood) 100%);
    color: var(--color-white);
    padding: var(--space-12) 0;
}

.events-header .region-breadcrumb {
    margin-bottom: var(--space-4);
}

.events-header .region-breadcrumb a {
    color: rgba(255,255,255,0.8);
}

.events-header .region-breadcrumb a:hover {
    color: var(--color-white);
}

.events-header__title {
    font-family: var(--font-display);
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: var(--space-2);
}

.events-header__subtitle {
    opacity: 0.9;
}

.events-filters {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-gray-200);
    padding: var(--space-4) 0;
    position: sticky;
    top: 60px;
    z-index: 100;
}

.filter-group {
    margin-bottom: var(--space-3);
}

.filter-group:last-child {
    margin-bottom: 0;
}

.filter-label {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--color-gray-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-2);
}

.area-filters {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
}

.area-filter {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
    font-size: 0.8125rem;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: all var(--transition-fast);
    border: 2px solid transparent;
}

.area-filter:hover {
    background: var(--color-gray-200);
    color: var(--color-gray-700);
    text-decoration: none;
}

.area-filter.active {
    background: var(--color-sunset);
    color: var(--color-white);
    border-color: var(--color-sunset);
}


/* ============================================
   Monthly Calendar Grid
   ============================================ */
.events-calendar-section {
    padding: var(--space-4) 0 0;
}

.region-calendar {
    max-width: 420px;
    margin: 0 auto var(--space-6);
    background: var(--color-white);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-sm);
    padding: var(--space-4);
}

.region-calendar__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: var(--space-3);
}

.region-calendar__month {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--color-gray-800);
}

.region-calendar__nav {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: var(--radius-full);
    color: var(--color-gray-600);
    text-decoration: none;
    transition: all var(--transition-fast);
}

.region-calendar__nav:hover {
    background: var(--color-gray-100);
    color: var(--color-ocean);
    text-decoration: none;
}

.region-calendar__table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.region-calendar__table th {
    text-align: center;
    font-size: 0.6875rem;
    font-weight: 600;
    color: var(--color-gray-400);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding-bottom: var(--space-2);
}

.region-calendar__day {
    text-align: center;
    padding: var(--space-1);
    vertical-align: middle;
    height: 40px;
}

.region-calendar__day--outside {
    background: none;
}

.region-calendar__day-link {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    margin: 0 auto;
    border-radius: var(--radius-full);
    text-decoration: none;
    color: var(--color-gray-700);
    font-size: 0.8125rem;
    font-weight: 500;
    position: relative;
    transition: all var(--transition-fast);
}

.region-calendar__day-link:hover {
    background: var(--color-gray-100);
    text-decoration: none;
    color: var(--color-ocean);
}

.region-calendar__day-num {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    margin: 0 auto;
    font-size: 0.8125rem;
    color: var(--color-gray-400);
}

.region-calendar__dot {
    display: block;
    width: 5px;
    height: 5px;
    border-radius: var(--radius-full);
    background: var(--color-ocean);
    position: absolute;
    bottom: 3px;
}

.region-calendar__day--today .region-calendar__day-link,
.region-calendar__day--today .region-calendar__day-num {
    font-weight: 700;
    color: var(--color-ocean);
}

.region-calendar__day--selected .region-calendar__day-link {
    background: var(--color-ocean);
    color: var(--color-white);
}

.region-calendar__day--selected .region-calendar__dot {
    background: var(--color-white);
}

.region-calendar__clear {
    text-align: center;
    padding-top: var(--space-3);
    border-top: 1px solid var(--color-gray-100);
    margin-top: var(--space-2);
}

.region-calendar__clear-link {
    font-size: 0.8125rem;
    color: var(--color-gray-500);
    text-decoration: none;
}

.region-calendar__clear-link:hover {
    color: var(--color-sunset);
    text-decoration: none;
}

.region-calendar__clear-link i {
    font-size: 0.75rem;
}


/* ============================================
   List / Map View Toggle
   ============================================ */
.view-toggle {
    display: inline-flex;
    background: var(--color-gray-100);
    border-radius: var(--radius-full);
    padding: 3px;
    margin-bottom: var(--space-6);
}

.view-toggle__btn {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    border: none;
    border-radius: var(--radius-full);
    background: transparent;
    color: var(--color-gray-500);
    font-size: 0.8125rem;
    font-weight: 500;
    cursor: pointer;
    transition: all var(--transition-fast);
}

.view-toggle__btn:hover {
    color: var(--color-gray-700);
}

.view-toggle__btn--active {
    background: var(--color-white);
    color: var(--color-gray-800);
    box-shadow: var(--shadow-sm);
}


/* ============================================
   Region Map
   ============================================ */
.region-map {
    min-height: 400px;
    max-height: 600px;
    height: 50vh;
    border-radius: var(--radius-xl);
    overflow: hidden;
    z-index: 0;
}

.region-map-popup {
    font-family: var(--font-body);
}

.region-map-popup__venue {
    font-weight: 600;
    font-size: 0.9375rem;
    color: var(--color-gray-800);
    margin-bottom: var(--space-1);
}

.region-map-popup__address {
    font-size: 0.8125rem;
    color: var(--color-gray-500);
    margin-bottom: var(--space-2);
}

.region-map-popup__list {
    list-style: none;
    padding: 0;
    margin: 0 0 var(--space-2);
}

.region-map-popup__list li {
    font-size: 0.8125rem;
    padding: var(--space-1) 0;
    border-bottom: 1px solid var(--color-gray-100);
}

.region-map-popup__list li:last-child {
    border-bottom: none;
}

.region-map-popup__list a {
    color: var(--color-ocean);
    text-decoration: none;
}

.region-map-popup__list a:hover {
    text-decoration: underline;
}

.region-map-popup__actions {
    margin-top: var(--space-2);
}

.region-map-popup__link {
    font-size: 0.75rem;
    color: var(--color-ocean);
    text-decoration: none;
}

.region-map-popup__link:hover {
    text-decoration: underline;
}


/* ============================================
   CTA Section
   ============================================ */
.cta-section,
.explore-cta {
    background: linear-gradient(135deg, var(--color-ocean) 0%, var(--color-ocean-dark) 100%);
    color: var(--color-white);
}

.cta-card {
    background: rgba(255,255,255,0.1);
    border-radius: var(--radius-2xl);
    padding: var(--space-10);
    text-align: center;
    backdrop-filter: blur(10px);
}

.cta-card__title {
    font-family: var(--font-display);
    font-size: 2rem;
    font-weight: 700;
    margin-bottom: var(--space-4);
    color: var(--color-white);
}

.cta-card__text {
    font-size: 1.125rem;
    opacity: 0.9;
    margin-bottom: var(--space-6);
    max-width: 500px;
    margin-left: auto;
    margin-right: auto;
}

.cta-card__buttons {
    display: flex;
    gap: var(--space-4);
    justify-content: center;
    flex-wrap: wrap;
    margin-bottom: var(--space-6);
}

.cta-card__features {
    display: flex;
    justify-content: center;
    gap: var(--space-8);
    flex-wrap: wrap;
    margin-top: var(--space-6);
    padding-top: var(--space-6);
    border-top: 1px solid rgba(255,255,255,0.2);
}

.cta-card__features .feature {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.875rem;
    opacity: 0.9;
}

.cta-card__features .feature i {
    font-size: 1.25rem;
}


/* ============================================
   Buttons
   ============================================ */
.btn-white {
    background: var(--color-white);
    color: var(--color-ocean);
    border: 2px solid var(--color-white);
    font-weight: 600;
}

.btn-white:hover {
    background: transparent;
    color: var(--color-white);
}

.btn-outline-white {
    background: transparent;
    color: var(--color-white);
    border: 2px solid rgba(255,255,255,0.5);
    font-weight: 600;
}

.btn-outline-white:hover {
    background: var(--color-white);
    color: var(--color-ocean);
    border-color: var(--color-white);
}


/* ============================================
   Saved Events Indicator
   ============================================ */
.saved-events-indicator {
    position: fixed;
    bottom: var(--space-6);
    right: var(--space-6);
    z-index: 1000;
}

.saved-events-link {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    background: var(--color-ocean);
    color: var(--color-white);
    padding: var(--space-3) var(--space-5);
    border-radius: var(--radius-full);
    text-decoration: none;
    font-weight: 600;
    box-shadow: var(--shadow-xl);
    transition: all var(--transition-normal);
}

.saved-events-link:hover {
    background: var(--color-ocean-dark);
    color: var(--color-white);
    transform: translateY(-2px);
}

.saved-events-link .saved-count {
    background: var(--color-white);
    color: var(--color-ocean);
    width: 24px;
    height: 24px;
    border-radius: var(--radius-full);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 0.75rem;
}

.saved-events-link .saved-cta {
    opacity: 0.9;
    font-size: 0.875rem;
}


/* ============================================
   Signup Prompt Toast
   ============================================ */
.signup-prompt-toast {
    position: fixed;
    bottom: var(--space-24);
    right: var(--space-6);
    z-index: 1001;
    animation: slideInRight 0.3s ease;
}

@keyframes slideInRight {
    from {
        opacity: 0;
        transform: translateX(100%);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

.signup-prompt-toast .toast-content {
    background: var(--color-white);
    padding: var(--space-5);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-xl);
    max-width: 300px;
}

.signup-prompt-toast strong {
    display: block;
    margin-bottom: var(--space-2);
    color: var(--color-gray-900);
}

.signup-prompt-toast p {
    font-size: 0.875rem;
    color: var(--color-gray-600);
    margin-bottom: var(--space-3);
}


/* ============================================
   Empty States
   ============================================ */
.empty-state {
    text-align: center;
    padding: var(--space-12) var(--space-6);
    color: var(--color-gray-500);
}

.empty-state > i {
    font-size: 3rem;
    opacity: 0.3;
    margin-bottom: var(--space-4);
    display: block;
}

.empty-state p {
    margin-bottom: var(--space-4);
}


/* ============================================
   Footer
   ============================================ */
.regions-footer {
    background: var(--color-gray-900);
    color: var(--color-gray-400);
    padding: var(--space-12) 0 var(--space-6);
}

.regions-footer .footer-brand {
    font-family: var(--font-display);
    font-size: 1.5rem;
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-3);
}

.regions-footer h6 {
    color: var(--color-white);
    font-weight: 600;
    margin-bottom: var(--space-3);
    font-family: var(--font-body);
    font-size: 0.875rem;
    text-transform: uppercase;
    letter-spacing: 0.05em;
}

.regions-footer ul {
    padding: 0;
}

.regions-footer a {
    color: var(--color-gray-400);
    text-decoration: none;
    transition: color var(--transition-fast);
}

.regions-footer a:hover {
    color: var(--color-white);
}

.regions-footer hr {
    border-color: var(--color-gray-700);
    margin: var(--space-8) 0 var(--space-4);
}


/* ============================================
   About Section
   ============================================ */
.region-about {
    background: var(--color-sand);
}

.about-content {
    text-align: center;
}

.about-content h2 {
    font-family: var(--font-display);
    font-size: 1.75rem;
    margin-bottom: var(--space-4);
}

.about-content p {
    color: var(--color-gray-700);
    line-height: 1.8;
    font-size: 1.1rem;
}


/* ============================================
   Pagination
   ============================================ */
.pagination-wrapper {
    margin-top: var(--space-8);
}

.pagination .page-link {
    color: var(--color-ocean);
    border-color: var(--color-gray-200);
    padding: var(--space-3) var(--space-4);
}

.pagination .page-link:hover {
    background: var(--color-ocean);
    color: var(--color-white);
    border-color: var(--color-ocean);
}

.pagination .page-item.disabled .page-link {
    color: var(--color-gray-500);
}


/* ============================================
   Responsive Design
   ============================================ */
@media (max-width: 768px) {
    .region-hero {
        min-height: 60vh;
    }

    .region-hero__title {
        font-size: 2.5rem;
    }

    .region-hero__cta {
        flex-direction: column;
    }

    .region-hero__cta .btn {
        width: 100%;
    }

    .cta-card__features {
        flex-direction: column;
        gap: var(--space-4);
    }

    .saved-events-indicator {
        bottom: var(--space-4);
        right: var(--space-4);
        left: var(--space-4);
    }

    .saved-events-link {
        justify-content: center;
    }

    .signup-prompt-toast {
        left: var(--space-4);
        right: var(--space-4);
        bottom: var(--space-20);
    }

    .event-detail-card {
        padding: var(--space-5);
    }

    .event-detail__hero {
        margin: calc(-1 * var(--space-5));
        margin-bottom: var(--space-5);
        padding: var(--space-6);
    }

    .event-detail__menu-grid {
        grid-template-columns: 1fr;
    }

    .event-detail__title {
        font-size: 1.75rem;
    }

    .event-detail__hours {
        margin-top: var(--space-4);
    }

    .event-detail__hours > .event-detail__hours-pills {
        display: none;
    }

    .event-detail__hours-mobile {
        display: block;
    }

    .event-detail__hours-toggle {
        flex-direction: column;
        align-items: stretch;
    }

    .event-detail__hours-toggle-text {
        padding-left: var(--space-1);
    }

    .region-calendar {
        max-width: 100%;
    }

    .region-map {
        min-height: 300px;
        height: 40vh;
    }
}
