}', 'originalFile': '/**
 * Regional Calendar - Editorial Design System
 *
 * Aesthetic: Coastal Editorial - Magazine meets travel guide
 * Typography: Playfair Display (display) + System Stack (body)
 * Colors: Teal ocean (#45B7D1) + Warm sand (#f5e6d3)
 */

/* ============================================
   CSS Custom Properties - Design Tokens
   ============================================ */
:root {
    /* Typography */
    --font-display: 'Playfair Display', Georgia, serif;
    --font-body: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;

    /* Colors - Coastal Palette */
    --color-ocean: #45B7D1;
    --color-ocean-dark: #3AA3BD;
    --color-ocean-light: #6EC8DD;
    --color-sand: #f5e6d3;
    --color-sand-dark: #e6d4be;
    --color-driftwood: #8B7355;
    --color-sunset: #FF6B6B;
    --color-seafoam: #88D8B0;

    /* Neutral Scale */
    --color-white: #ffffff;
    --color-gray-50: #f9fafb;
    --color-gray-100: #f3f4f6;
    --color-gray-200: #e5e7eb;
    --color-gray-300: #d1d5db;
    --color-gray-400: #9ca3af;
    --color-gray-500: #6b7280;
    --color-gray-600: #4b5563;
    --color-gray-700: #374151;
    --color-gray-800: #1f2937;
    --color-gray-900: #111827;

    /* Spacing Scale */
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-5: 1.25rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-10: 2.5rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-20: 5rem;
    --space-24: 6rem;

    /* Border Radius */
    --radius-sm: 0.25rem;
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;
    --radius-2xl: 1.5rem;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
    --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

    /* Transitions */
    --transition-fast: 150ms ease;
    --transition-normal: 300ms ease;
    --transition-slow: 500ms ease;
}


/* ============================================
   Base Styles
   ============================================ */
.regions-public {
    font-family: var(--font-body);
    color: var(--color-gray-800);
    background-color: var(--color-white);
    line-height: 1.6;
    padding-top: 0;
}

.regions-public h1,
.regions-public h2,
.regions-public h3,
.regions-public h4 {
    font-family: var(--font-display);
    font-weight: 600;
    line-height: 1.2;
    color: var(--color-gray-900);
}


/* ============================================
   Navigation
   ============================================ */
.regions-navbar {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-gray-200);
    padding: 0;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.regions-navbar > .container.regions-navbar__inner {
    min-height: 4rem;
    padding: var(--space-1) var(--space-4);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
}

.regions-navbar__brand {
    padding: 0;
    margin: 0;
    display: inline-flex;
    align-items: center;
    min-height: auto;
    white-space: nowrap;
}

.regions-navbar__brand.navbar-brand {
    font-size: var(--font-size-xl);
    line-height: 1;
}

.regions-navbar__actions {
    align-items: center;
    gap: var(--space-2);
    flex-wrap: wrap;
    row-gap: var(--space-2);
}

.regions-navbar .nav-link {
    font-weight: 500;
    color: var(--color-gray-600);
    padding: var(--space-1) var(--space-3);
    min-height: 2.25rem;
    display: inline-flex;
    align-items: center;
    border-radius: var(--radius);
    transition: color var(--transition-fast), background-color var(--transition-fast);
}

.regions-navbar .nav-link:hover,
.regions-navbar .nav-link.active {
    color: var(--color-ocean);
    background: rgba(69, 183, 209, 0.08);
}

.regions-navbar__cta {
    min-height: 2.25rem;
    padding: 0.5rem 0.9rem;
    display: inline-flex;
    align-items: center;
}

@media (max-width: 768px) {
    .regions-navbar > .container.regions-navbar__inner {
        padding: var(--space-1) var(--space-3);
        gap: var(--space-3);
    }

    .regions-navbar__brand.navbar-brand {
        font-size: 1.05rem;
    }

    .regions-navbar__actions {
        gap: var(--space-1);
        justify-content: flex-end;
    }

    .regions-navbar .nav-link,
    .regions-navbar__cta {
        min-height: 2.25rem;
    }
}


/* ============================================
   Hero Sections
   ============================================ */

/* Explore Page Hero */
.explore-hero {
    min-height: 50vh;
    background:
        linear-gradient(135deg, rgba(69, 183, 209, 0.9) 0%, rgba(139, 115, 85, 0.8) 100%),
        url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600') center/cover;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: var(--color-white);
}

.explore-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.4) 100%);
}

.explore-hero__content {
    position: relative;
    z-index: 1;
    padding: var(--space-8) var(--space-6);
}

.explore-hero__badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    background: rgba(255,255,255,0.2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-bottom: var(--space-4);
}

.explore-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2.5rem, 6vw, 4rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-4);
    text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}

.explore-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    max-width: 600px;
    margin: 0 auto;
}

/* Region Detail Hero */
.region-hero {
    min-height: clamp(280px, 42vh, 440px);
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    position: relative;
    display: flex;
    align-items: flex-end;
    color: var(--color-white);
}

.region-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.8) 100%);
}

.region-hero__content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-8) var(--space-6);
}

.region-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 6vw, 3.25rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-2);
    text-shadow: 0 2px 30px rgba(0,0,0,0.4);
}

.region-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    margin-bottom: var(--space-6);
}

.region-hero__cta {
    display: flex;
    gap: var(--space-4);
    flex-wrap: wrap;
}

/* Breadcrumb */
.region-breadcrumb {
    font-size: 0.875rem;
    margin-bottom: var(--space-4);
    opacity: 0.8;
}

.region-breadcrumb a {
    color: inherit;
    text-decoration: none;
}

.region-breadcrumb a:hover {
    text-decoration: underline;
}

.region-breadcrumb .separator {
    margin: 0 var(--space-2);
    opacity: 0.5;
}

.region-breadcrumb .current {
    opacity: 0.7;
}


/* ============================================
   Specials Pages
   ============================================ */
.specials-hero {
    min-height: 52vh;
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    color: var(--color-white);
    position: relative;
    display: flex;
    align-items: flex-end;
}

.specials-hero__overlay {
    position: absolute;
    inset: 0;
    background:
        linear-gradient(145deg, rgba(255, 107, 107, 0.32), rgba(69, 183, 209, 0.2)),
        linear-gradient(180deg, rgba(11, 20, 28, 0.16), rgba(11, 20, 28, 0.82));
}

.specials-hero__content {
    position: relative;
    z-index: 1;
