    --color-gray-600: #4b5563;
    --color-gray-700: #374151;
    --color-gray-800: #1f2937;
    --color-gray-900: #111827;

    /* Spacing Scale */
    --space-1: 0.25rem;
    --space-2: 0.5rem;
    --space-3: 0.75rem;
    --space-4: 1rem;
    --space-5: 1.25rem;
    --space-6: 1.5rem;
    --space-8: 2rem;
    --space-10: 2.5rem;
    --space-12: 3rem;
    --space-16: 4rem;
    --space-20: 5rem;
    --space-24: 6rem;

    /* Border Radius */
    --radius-sm: 0.25rem;
    --radius-md: 0.5rem;
    --radius-lg: 0.75rem;
    --radius-xl: 1rem;
    --radius-2xl: 1.5rem;
    --radius-full: 9999px;

    /* Shadows */
    --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
    --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.1), 0 2px 4px -2px rgb(0 0 0 / 0.1);
    --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.1), 0 4px 6px -4px rgb(0 0 0 / 0.1);
    --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.1), 0 8px 10px -6px rgb(0 0 0 / 0.1);

    /* Transitions */
    --transition-fast: 150ms ease;
    --transition-normal: 300ms ease;
    --transition-slow: 500ms ease;
}


/* ============================================
   Base Styles
   ============================================ */
.regions-public {
    font-family: var(--font-body);
    color: var(--color-gray-800);
    background-color: var(--color-white);
    line-height: 1.6;
    padding-top: 0;
}

.regions-public h1,
.regions-public h2,
.regions-public h3,
.regions-public h4 {
    font-family: var(--font-display);
    font-weight: 600;
    line-height: 1.2;
    color: var(--color-gray-900);
}


/* ============================================
   Navigation
   ============================================ */
.regions-navbar {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-gray-200);
    padding: 0;
    position: sticky;
    top: 0;
    z-index: 1000;
}

.regions-navbar > .container.regions-navbar__inner {
    min-height: 4rem;
    padding: var(--space-1) var(--space-4);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
}

.regions-navbar__brand {
    padding: 0;
    margin: 0;
    display: inline-flex;
    align-items: center;
    min-height: auto;
    white-space: nowrap;
}

.regions-navbar__brand.navbar-brand {
    font-size: var(--font-size-xl);
    line-height: 1;
}

.regions-navbar__actions {
    align-items: center;
    gap: var(--space-2);
    flex-wrap: wrap;
    row-gap: var(--space-2);
}

.regions-navbar .nav-link {
    font-weight: 500;
    color: var(--color-gray-600);
    padding: var(--space-1) var(--space-3);
    min-height: 2.25rem;
    display: inline-flex;
    align-items: center;
    border-radius: var(--radius);
    transition: color var(--transition-fast), background-color var(--transition-fast);
}

.regions-navbar .nav-link:hover,
.regions-navbar .nav-link.active {
    color: var(--color-ocean);
    background: rgba(69, 183, 209, 0.08);
}

.regions-navbar__cta {
    min-height: 2.25rem;
    padding: 0.5rem 0.9rem;
    display: inline-flex;
    align-items: center;
}

@media (max-width: 768px) {
    .regions-navbar > .container.regions-navbar__inner {
        padding: var(--space-1) var(--space-3);
        gap: var(--space-3);
    }

    .regions-navbar__brand.navbar-brand {
        font-size: 1.05rem;
    }

    .regions-navbar__actions {
        gap: var(--space-1);
        justify-content: flex-end;
    }

    .regions-navbar .nav-link,
    .regions-navbar__cta {
        min-height: 2.25rem;
    }
}


/* ============================================
   Hero Sections
   ============================================ */

/* Explore Page Hero */
.explore-hero {
    min-height: 50vh;
    background:
        linear-gradient(135deg, rgba(69, 183, 209, 0.9) 0%, rgba(139, 115, 85, 0.8) 100%),
        url('https://images.unsplash.com/photo-1507525428034-b723cf961d3e?w=1600') center/cover;
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    text-align: center;
    color: var(--color-white);
}

.explore-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.4) 100%);
}

.explore-hero__content {
    position: relative;
    z-index: 1;
    padding: var(--space-8) var(--space-6);
}

.explore-hero__badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.15em;
    background: rgba(255,255,255,0.2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-bottom: var(--space-4);
}

.explore-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2.5rem, 6vw, 4rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-4);
    text-shadow: 0 2px 20px rgba(0,0,0,0.3);
}

.explore-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    max-width: 600px;
    margin: 0 auto;
}

/* Region Detail Hero */
.region-hero {
    min-height: clamp(280px, 42vh, 440px);
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    position: relative;
    display: flex;
    align-items: flex-end;
    color: var(--color-white);
}

.region-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,0.25) 0%, rgba(0,0,0,0.8) 100%);
}

.region-hero__content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-8) var(--space-6);
}

.region-hero__title {
    font-family: var(--font-display);
    font-size: clamp(2rem, 6vw, 3.25rem);
    font-weight: 700;
    color: var(--color-white);
    margin-bottom: var(--space-2);
    text-shadow: 0 2px 30px rgba(0,0,0,0.4);
}

.region-hero__subtitle {
    font-size: 1.25rem;
    opacity: 0.9;
    margin-bottom: var(--space-6);
}

.region-hero__cta {
    display: flex;
    gap: var(--space-4);
    flex-wrap: wrap;
}

/* Breadcrumb */
.region-breadcrumb {
    font-size: 0.875rem;
    margin-bottom: var(--space-4);
    opacity: 0.8;
}

.region-breadcrumb a {
    color: inherit;
    text-decoration: none;
}

.region-breadcrumb a:hover {
    text-decoration: underline;
}

.region-breadcrumb .separator {
    margin: 0 var(--space-2);
    opacity: 0.5;
}

.region-breadcrumb .current {
    opacity: 0.7;
}


/* ============================================
   Specials Pages
   ============================================ */
.specials-hero {
    min-height: clamp(220px, 32vh, 340px);
    background: var(--hero-image, linear-gradient(135deg, var(--color-ocean), var(--color-driftwood))) center/cover;
    color: var(--color-white);
    position: relative;
    display: flex;
    align-items: flex-end;
}

.specials-hero__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(11, 20, 28, 0.35) 0%, rgba(11, 20, 28, 0.85) 100%);
}

.specials-hero__content {
    position: relative;
    z-index: 1;
    width: 100%;
    max-width: 1200px;
    margin: 0 auto;
    padding: var(--space-6) var(--space-6);
}

.specials-hero__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    background: rgba(255, 255, 255, 0.18);
    border: 1px solid rgba(255, 255, 255, 0.32);
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-4);
    margin-bottom: var(--space-4);
}

.specials-hero__title {
    color: var(--color-white);
    font-size: clamp(1.4rem, 3.2vw, 2.5rem);
    margin-bottom: var(--space-2);
    text-shadow: 0 2px 4px rgba(0, 0, 0, 0.6), 0 8px 24px rgba(0, 0, 0, 0.4);
}

.specials-hero__subtitle {
    font-size: 0.98rem;
    opacity: 0.95;
    margin-bottom: var(--space-5);
}

.specials-topbar {
    background: var(--color-warm-sand, #faf7f2);
    border-bottom: 1px solid rgba(0, 0, 0, 0.06);
    padding: var(--space-3) 0;
}

.specials-topbar__inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--space-6);
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-4);
}

.specials-topbar__text {
    font-size: 0.9rem;
    color: var(--gray-600, #4b5563);
    font-weight: 500;
}

.specials-topbar__actions {
    display: flex;
    gap: var(--space-2);
    flex-shrink: 0;
}

.specials-toolbar {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
}

.specials-filters {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
    margin-top: var(--space-5);
}

.specials-filters__chip {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.14);
    color: var(--color-white);
    border: 1px solid rgba(255, 255, 255, 0.22);
    font-weight: 600;
    text-decoration: none;
    transition: background-color 0.2s ease, transform 0.2s ease;
}

.specials-filters__chip:hover,
.specials-filters__chip--active {
    background: rgba(255, 255, 255, 0.92);
    color: var(--color-ocean-dark);
}

.specials-toolbar__link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    text-decoration: none;
    color: var(--color-white);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.12);
    border: 1px solid rgba(255, 255, 255, 0.2);
    transition: transform var(--transition-fast), background var(--transition-fast);
}

.specials-toolbar__link:hover {
    color: var(--color-white);
    transform: translateY(-1px);
    background: rgba(255, 255, 255, 0.2);
}

.specials-toolbar__link--primary {
    background: var(--color-sunset);
    border-color: transparent;
}

.specials-toolbar__link--copied {
    background: rgba(136, 216, 176, 0.24);
    border-color: rgba(136, 216, 176, 0.65);
}

.specials-listing {
    background:
        radial-gradient(circle at top right, rgba(136, 216, 176, 0.15), transparent 40%),
        linear-gradient(180deg, #fffefb 0%, #f7fafb 100%);
    padding: var(--space-12) 0 var(--space-20);
}

.specials-layout {
    display: block;
}

.specials-layout--with-map {
    display: grid;
    gap: var(--space-6);
}

.specials-map-panel {
    min-width: 0;
}

.specials-map-card {
    background: linear-gradient(180deg, rgba(255, 255, 255, 0.92), rgba(255, 255, 255, 0.98));
    border: 1px solid rgba(69, 183, 209, 0.16);
    border-radius: var(--radius-2xl);
    box-shadow: var(--shadow-lg);
    overflow: hidden;
}

.specials-map-card__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    margin: var(--space-5) var(--space-5) 0;
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: rgba(69, 183, 209, 0.12);
    color: var(--color-ocean-dark);
    font-size: 0.75rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.specials-map-card__title {
    margin: var(--space-4) var(--space-5) var(--space-2);
    font-size: clamp(1.75rem, 3vw, 2.5rem);
}

.specials-map-card__copy {
    margin: 0 var(--space-5) var(--space-4);
    color: var(--color-gray-600);
    max-width: 40rem;
}

.specials-map-card__stats {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
    margin: 0 var(--space-5) var(--space-5);
    color: var(--color-gray-700);
    font-size: 0.95rem;
    font-weight: 600;
}

.specials-map-card__stats span {
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: rgba(255, 255, 255, 0.85);
    border: 1px solid rgba(69, 183, 209, 0.14);
}

.specials-map {
    min-height: 320px;
    height: 42vh;
    max-height: 520px;
    border-top: 1px solid rgba(69, 183, 209, 0.12);
}

.specials-map .leaflet-popup-content-wrapper {
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-lg);
}

.specials-map-popup__venue {
    font-family: var(--font-display);
    font-size: 1.15rem;
    color: var(--color-gray-900);
    margin-bottom: var(--space-2);
}

.specials-map-popup__address {
    color: var(--color-gray-500);
    font-size: 0.9rem;
    margin-bottom: var(--space-3);
}

.specials-map-popup__list {
    margin: 0 0 var(--space-3);
    padding-left: 1rem;
    color: var(--color-gray-700);
}

.specials-map-popup__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
}

.specials-map-popup__focus,
.specials-map-popup__link {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 0.55rem 0.9rem;
    border-radius: var(--radius-full);
    font-size: 0.875rem;
    font-weight: 700;
    text-decoration: none;
}

.specials-map-popup__focus {
    border: none;
    background: var(--color-ocean);
    color: var(--color-white);
}

.specials-map-popup__link {
    background: rgba(69, 183, 209, 0.1);
    color: var(--color-ocean-dark);
}

.specials-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
    gap: var(--space-6);
}

.special-card {
    background: var(--color-white);
    border: 1px solid rgba(69, 183, 209, 0.14);
    border-radius: var(--radius-2xl);
    overflow: hidden;
    box-shadow: var(--shadow-lg);
    display: flex;
    flex-direction: column;
    transition: transform var(--transition-fast), box-shadow var(--transition-fast), border-color var(--transition-fast);
}

.special-card--map-active {
    border-color: rgba(255, 107, 107, 0.5);
    box-shadow: 0 24px 48px -24px rgba(255, 107, 107, 0.45), var(--shadow-xl);
    transform: translateY(-2px);
}

.special-card--map-flash {
    animation: special-card-map-flash 1.45s ease-out;
}

@keyframes special-card-map-flash {
    0% {
        border-color: rgba(255, 107, 107, 0.32);
        box-shadow: 0 0 0 0 rgba(255, 107, 107, 0.12), var(--shadow-xl);
        transform: translateY(-2px) scale(1);
    }
    18% {
        border-color: rgba(255, 107, 107, 0.95);
        box-shadow:
            0 0 0 8px rgba(255, 107, 107, 0.14),
            0 26px 56px -24px rgba(255, 107, 107, 0.52),
            var(--shadow-xl);
        transform: translateY(-4px) scale(1.012);
    }
    48% {
        border-color: rgba(255, 107, 107, 0.84);
        box-shadow:
            0 0 0 12px rgba(255, 107, 107, 0.08),
            0 26px 56px -24px rgba(255, 107, 107, 0.48),
            var(--shadow-xl);
        transform: translateY(-3px) scale(1.008);
    }
    100% {
        border-color: rgba(255, 107, 107, 0.5);
        box-shadow: 0 24px 48px -24px rgba(255, 107, 107, 0.45), var(--shadow-xl);
        transform: translateY(-2px) scale(1);
    }
}

.special-card__media {
    min-height: 130px;
    background:
        radial-gradient(circle at top left, rgba(255, 255, 255, 0.6), transparent 35%),
        linear-gradient(135deg, rgba(255, 107, 107, 0.18), rgba(69, 183, 209, 0.65));
    padding: var(--space-5);
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
}

.special-card__media--image {
    background-position: center;
    background-size: cover;
}

.special-card__badge,
.special-card__recurring {
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-3);
}

.special-card__badge {
    background: rgba(255, 255, 255, 0.92);
    color: var(--color-driftwood);
}

.special-card__badge--meal,
.special-card__badge--time {
    background: rgba(240, 249, 255, 0.92);
    color: var(--color-ocean-dark);
    border: 1px solid rgba(125, 211, 252, 0.42);
}

.special-card__recurring {
    background: rgba(17, 24, 39, 0.72);
    color: var(--color-white);
}

.special-card__body {
    padding: var(--space-6);
}

.special-card__header {
    display: flex;
    justify-content: space-between;
    gap: var(--space-4);
    margin-bottom: var(--space-4);
}

.special-card__title {
    font-size: 1.5rem;
    margin-bottom: var(--space-2);
}

.special-card__location,
.special-card__address {
    color: var(--color-gray-600);
}

.special-card__location {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 600;
}

.special-card__address {
    margin-top: var(--space-2);
    font-size: 0.95rem;
}

.special-card__time {
    white-space: nowrap;
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--color-ocean-dark);
    background: rgba(69, 183, 209, 0.12);
    border-radius: var(--radius-full);
    padding: var(--space-2) var(--space-3);
    align-self: flex-start;
}

.special-card__lede {
    color: var(--color-gray-700);
    margin-bottom: var(--space-4);
}

.special-card__menu {
    list-style: none;
    padding: 0;
    margin: 0 0 var(--space-5);
    display: grid;
    gap: var(--space-3);
}

.special-card__menu li {
    position: relative;
    padding: var(--space-3) var(--space-4) var(--space-3) 2rem;
    color: var(--color-gray-800);
    border-radius: var(--radius-lg);
    background: rgba(255, 255, 255, 0.82);
    border: 1px solid rgba(154, 52, 18, 0.08);
    min-height: 100%;
}

.special-card__menu li::before {
    content: "•";
    position: absolute;
    left: 0.85rem;
    top: 0.9rem;
    color: var(--color-sunset);
    font-size: 1.2rem;
    line-height: 1;
}

.special-card__menu-more {
    margin-top: calc(var(--space-4) * -1);
    margin-bottom: var(--space-5);
    color: var(--color-gray-600);
    font-weight: 600;
}

.special-card__promo-list {
    list-style: none;
    padding: 0;
    margin: calc(var(--space-4) * -1) 0 var(--space-5);
    display: grid;
    gap: var(--space-2);
}

.special-card__promo-item {
    position: relative;
    padding-left: 1.35rem;
    color: var(--color-gray-600);
    font-size: 0.95rem;
    line-height: 1.5;
}

.special-card__promo-item::before {
    content: "•";
    position: absolute;
    left: 0.25rem;
    top: 0.05rem;
    color: rgba(14, 116, 144, 0.68);
    font-size: 1rem;
    line-height: 1;
}

.special-card__copy {
    color: var(--color-gray-700);
    margin-bottom: var(--space-5);
}

.special-card__copy p:last-child {
    margin-bottom: 0;
}

.special-card__actions {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-3);
    margin-top: var(--space-5);
}

.specials-empty-state {
    padding: var(--space-16) var(--space-8);
}

@media (max-width: 768px) {
    .explore-hero__content,
    .specials-hero__content {
        padding: var(--space-8) var(--space-4);
    }

    .specials-topbar__inner {
        flex-direction: column;
        text-align: center;
        gap: var(--space-2);
        padding: 0 var(--space-4);
    }

    .specials-toolbar {
        flex-direction: column;
        align-items: stretch;
    }

    .special-card__header {
        flex-direction: column;
    }

    .specials-map {
        height: 320px;
    }
}

@media (min-width: 992px) {
    .specials-layout--with-map {
        grid-template-columns: minmax(340px, 420px) minmax(0, 1fr);
        align-items: start;
    }

    .specials-map-panel {
        position: sticky;
        top: calc(88px + var(--space-4));
    }
}


/* ============================================
   Section Styles
   ============================================ */
section {
    padding: var(--space-12) 0;
}

.section-title {
    font-family: var(--font-display);
    font-size: 2rem;
    font-weight: 600;
    margin-bottom: var(--space-6);
    color: var(--color-gray-900);
}

.section-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: var(--space-6);
}

.view-all-link {
    font-weight: 500;
    color: var(--color-ocean);
    text-decoration: none;
    display: flex;
    align-items: center;
    gap: var(--space-2);
}

.view-all-link:hover {
    color: var(--color-ocean-dark);
}

/* Featured Regions */
.featured-regions {
    background: var(--color-gray-50);
}

/* All Regions */
.all-regions {
    background: var(--color-white);
}


/* ============================================
   Region Cards
   ============================================ */
.region-card {
    display: block;
    text-decoration: none;
    color: inherit;
    background: var(--color-white);
    border-radius: var(--radius-xl);
    overflow: hidden;
    box-shadow: var(--shadow-md);
    transition: transform var(--transition-normal), box-shadow var(--transition-normal);
}

.region-card:hover {
    transform: translateY(-4px);
    box-shadow: var(--shadow-xl);
    color: inherit;
    text-decoration: none;
}

.region-card__image {
    height: 200px;
    background-size: cover;
    background-position: center;
    position: relative;
}

.region-card__image--small {
    height: 140px;
}

.region-card__overlay {
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, transparent 50%, rgba(0,0,0,0.3) 100%);
}

.region-card__badge {
    position: absolute;
    top: var(--space-3);
    left: var(--space-3);
    background: var(--color-ocean);
    color: var(--color-white);
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-1) var(--space-3);
    border-radius: var(--radius-full);
}

.region-card__content {
    padding: var(--space-4);
}

.region-card__title {
    font-family: var(--font-display);
    font-size: 1.25rem;
    font-weight: 600;
    margin-bottom: var(--space-2);
    color: var(--color-gray-900);
}

.region-card__tagline {
    font-size: 0.875rem;
    color: var(--color-gray-600);
    margin-bottom: var(--space-3);
    line-height: 1.5;
}

.region-card__meta {
    font-size: 0.875rem;
    color: var(--color-gray-500);
}

.region-card__events {
    display: flex;
    align-items: center;
    gap: var(--space-2);
}


/* ============================================
   Event Cards
   ============================================ */
.event-card {
    background: var(--color-white);
    border-radius: var(--radius-lg);
    border: 1px solid var(--color-gray-200);
    overflow: hidden;
    position: relative;
    transition: transform var(--transition-normal), box-shadow var(--transition-normal), border-color var(--transition-normal);
}

.event-card:hover {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    border-color: var(--color-ocean-light);
}

.event-card__link {
    display: block;
    padding: var(--space-4);
    text-decoration: none;
    color: inherit;
}

.event-card__link:hover {
    color: inherit;
    text-decoration: none;
}

.event-card__category {
    display: inline-block;
    font-size: 0.7rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-sm);
    margin-bottom: var(--space-2);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
}

/* Category Colors */
.event-card__category--event { background: #dbeafe; color: #1e40af; }
.event-card__category--food { background: #ffedd5; color: #9a3412; }

/* Recurring Badge - shows "Weekly", "Daily", etc. */
.event-card__recurring-badge {
    display: inline-block;
    font-size: 0.65rem;
    font-weight: 500;
    text-transform: uppercase;
    letter-spacing: 0.03em;
    padding: 2px 6px;
    border-radius: var(--radius-sm);
    margin-left: var(--space-2);
    background: var(--color-gray-100);
    color: var(--color-gray-500);
    vertical-align: middle;
}

.event-card__content {
    min-height: 80px;
}

.event-card__title {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 600;
    margin-bottom: var(--space-2);
    color: var(--color-gray-900);
    line-height: 1.3;
}

.event-card__meta {
    display: flex;
    gap: var(--space-4);
    font-size: 0.875rem;
    color: var(--color-gray-500);
    margin-bottom: var(--space-2);
}

.event-card__date,
.event-card__time {
    display: flex;
    align-items: center;
    gap: var(--space-1);
}

.event-card__location {
    font-size: 0.875rem;
    color: var(--color-gray-500);
    display: flex;
    align-items: center;
    gap: var(--space-1);
}

/* Save Button */
.event-card__save-btn {
    position: absolute;
    top: var(--space-3);
    right: var(--space-3);
    width: 36px;
    height: 36px;
    border: none;
    border-radius: var(--radius-full);
    background: var(--color-white);
    color: var(--color-gray-400);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    box-shadow: var(--shadow-md);
    transition: all var(--transition-fast);
}

.event-card__save-btn:hover {
    color: var(--color-ocean);
    transform: scale(1.1);
}

.event-card__save-btn.saved {
    background: var(--color-ocean);
    color: var(--color-white);
}


/* ============================================
   Category Filters
   ============================================ */
.category-filters {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
    padding: var(--space-4) 0;
}

.category-filter {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
    font-size: 0.875rem;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: all var(--transition-fast);
    border: 2px solid transparent;
}

.category-filter:hover {
    background: var(--color-gray-200);
    color: var(--color-gray-700);
    text-decoration: none;
}

.category-filter.active {
    background: var(--color-ocean);
    color: var(--color-white);
    border-color: var(--color-ocean);
}


/* ============================================
   Event Detail Page
   ============================================ */
.event-detail-page {
    padding-bottom: var(--space-16);
}

.event-detail-card {
    background: var(--color-white);
    border-radius: var(--radius-xl);
    padding: var(--space-6);
    box-shadow: var(--shadow-lg);
    margin-top: var(--space-6);
    overflow: hidden;
}

.event-category-badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-bottom: var(--space-4);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
}

/* Category badge colors */
.event-category-badge--festival { background: #fef3c7; color: #92400e; }
.event-category-badge--concert { background: #fce7f3; color: #9d174d; }
.event-category-badge--market { background: #d1fae5; color: #065f46; }
.event-category-badge--community { background: #dbeafe; color: #1e40af; }
.event-category-badge--nature { background: #dcfce7; color: #166534; }
.event-category-badge--sports { background: #fee2e2; color: #991b1b; }
.event-category-badge--food { background: #ffedd5; color: #9a3412; }

.event-meal-period-badge {
    display: inline-block;
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: var(--space-2) var(--space-4);
    border-radius: var(--radius-full);
    margin-left: var(--space-2);
    margin-bottom: var(--space-4);
    background: rgba(186, 230, 253, 0.24);
    color: inherit;
    border: 1px solid rgba(255, 255, 255, 0.18);
}

.event-detail__hero {
    margin: calc(-1 * var(--space-6));
    margin-bottom: var(--space-6);
    padding: var(--space-8);
    border-radius: var(--radius-xl);
    position: relative;
    overflow: hidden;
    background-size: cover;
    background-position: center;
}

.event-detail__hero--fallback {
    background:
        radial-gradient(circle at top right, rgba(255,255,255,0.25), transparent 32%),
        linear-gradient(135deg, #10324a 0%, #1d5c7f 54%, #d97706 100%);
    color: var(--color-white);
}

.event-detail__hero--fallback.event-detail__hero--food {
    background:
        radial-gradient(circle at top right, rgba(255,248,235,0.38), transparent 30%),
        linear-gradient(135deg, #7c2d12 0%, #c2410c 52%, #f59e0b 100%);
}

.event-detail__hero--image {
    color: var(--color-white);
    min-height: 320px;
    display: flex;
    align-items: end;
}

.event-detail__hero-copy {
    max-width: 42rem;
    position: relative;
    z-index: 1;
}

.event-detail__eyebrow {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    margin-bottom: var(--space-3);
    opacity: 0.92;
}

.event-detail__title {
    font-family: var(--font-display);
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: var(--space-4);
    color: var(--color-gray-900);
}

.event-detail__hero .event-detail__title {
    color: inherit;
    margin-bottom: var(--space-3);
}

.event-detail__lede {
    margin: 0;
    font-size: 1.05rem;
    line-height: 1.75;
    max-width: 38rem;
    color: inherit;
    opacity: 0.96;
}

.event-detail__datetime,
.event-detail__location {
    display: flex;
    gap: var(--space-4);
    margin-bottom: var(--space-4);
    padding: var(--space-4);
    background: var(--color-gray-50);
    border-radius: var(--radius-lg);
}

.event-detail__datetime i,
.event-detail__location i {
    font-size: 1.5rem;
    color: var(--color-ocean);
}

.event-date {
    font-weight: 600;
    color: var(--color-gray-900);
}

.event-time {
    color: var(--color-gray-600);
}

.location-name {
    font-weight: 600;
    color: var(--color-gray-900);
}

.location-address {
    color: var(--color-gray-600);
}

.event-detail__description {
    margin: var(--space-6) 0;
    color: var(--color-gray-700);
    line-height: 1.8;
}

.event-detail__place-card {
    margin: var(--space-6) 0;
    padding: var(--space-6);
    border-radius: var(--radius-xl);
    background:
        linear-gradient(180deg, rgba(248, 250, 252, 0.92), rgba(255,255,255,0.98)),
        linear-gradient(135deg, rgba(219, 234, 254, 0.7), rgba(240, 249, 255, 0.85));
    border: 1px solid rgba(37, 99, 235, 0.12);
}

.event-detail__place-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: var(--space-3);
}

.event-detail__place-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-3);
    padding: var(--space-4);
    border-radius: var(--radius-lg);
    text-decoration: none;
    color: var(--color-gray-800);
    background: rgba(255,255,255,0.92);
    border: 1px solid rgba(59, 130, 246, 0.12);
    transition: transform var(--transition-fast), box-shadow var(--transition-fast);
}

.event-detail__place-link:hover {
    color: var(--color-ocean-dark);
    text-decoration: none;
    transform: translateY(-1px);
    box-shadow: var(--shadow-md);
}

.event-detail__rating {
    margin-top: var(--space-4);
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    font-weight: 600;
    color: var(--color-gray-900);
}

.event-detail__rating i {
    color: #f59e0b;
}

.event-detail__rating-count {
    color: var(--color-gray-600);
    font-weight: 500;
}

.event-detail__hours {
    margin-top: var(--space-5);
}

.event-detail__hours-label {
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-gray-500);
    margin-bottom: var(--space-2);
}

.event-detail__hours-pills {
    display: flex;
    flex-wrap: wrap;
    gap: var(--space-2);
}

.event-detail__hours-pill {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: rgba(255,255,255,0.92);
    border: 1px solid rgba(15, 23, 42, 0.08);
    color: var(--color-gray-700);
    line-height: 1.2;
}

.event-detail__hours-pill--current {
    background: rgba(69, 183, 209, 0.12);
    border-color: rgba(58, 163, 189, 0.28);
    color: var(--color-ocean-dark);
}

.event-detail__hours-day {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 2.4rem;
    padding: var(--space-1) var(--space-2);
    border-radius: var(--radius-full);
    background: rgba(15, 23, 42, 0.06);
    color: var(--color-gray-600);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.event-detail__hours-pill--current .event-detail__hours-day {
    background: rgba(69, 183, 209, 0.18);
    color: var(--color-ocean-dark);
}

.event-detail__hours-value {
    font-size: 0.92rem;
    font-weight: 600;
}

.event-detail__hours-mobile {
    display: none;
    margin-top: var(--space-2);
}

.event-detail__hours-toggle {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--space-3);
    cursor: pointer;
    list-style: none;
}

.event-detail__hours-toggle::-webkit-details-marker {
    display: none;
}

.event-detail__hours-toggle-text {
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--color-ocean-dark);
}

.event-detail__hours-toggle-label--open,
.event-detail__hours-mobile[open] .event-detail__hours-toggle-label--closed {
    display: none;
}

.event-detail__hours-mobile[open] .event-detail__hours-toggle-label--open {
    display: inline;
}

.event-detail__hours-pills--mobile-expanded {
    margin-top: var(--space-2);
}

.event-detail__description p:last-child {
    margin-bottom: 0;
}

.event-detail__menu-board {
    margin: var(--space-6) 0;
    padding: var(--space-6);
    border-radius: var(--radius-xl);
    background:
        linear-gradient(180deg, rgba(255,255,255,0.7), rgba(255,255,255,0.96)),
        linear-gradient(135deg, rgba(255,237,213,0.8), rgba(255,251,235,0.85));
    border: 1px solid rgba(249, 115, 22, 0.16);
}

.event-detail__section-label {
    font-size: 0.8rem;
    font-weight: 700;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--color-gray-500);
    margin-bottom: var(--space-4);
}

.event-detail__menu-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
    gap: var(--space-3);
}

.event-detail__menu-item {
    display: flex;
    align-items: start;
    gap: var(--space-3);
    padding: var(--space-4);
    border-radius: var(--radius-lg);
    background: rgba(255,255,255,0.85);
    border: 1px solid rgba(154, 52, 18, 0.08);
    color: var(--color-gray-800);
    font-weight: 500;
    min-height: 100%;
}

.event-detail__menu-item-icon {
    width: 2rem;
    height: 2rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: rgba(245, 158, 11, 0.16);
    color: #b45309;
    flex: 0 0 auto;
}

.event-detail__promo-list {
    list-style: none;
    padding: 0;
    margin: calc(var(--space-5) * -1) 0 var(--space-6);
    display: grid;
    gap: var(--space-3);
}

.event-detail__promo-item {
    display: flex;
    align-items: start;
    gap: var(--space-3);
    padding: var(--space-3) var(--space-4);
    border-radius: var(--radius-lg);
    background: rgba(248, 250, 252, 0.88);
    border: 1px solid rgba(148, 163, 184, 0.24);
    color: var(--color-gray-700);
    font-size: 0.97rem;
}

.event-detail__promo-item-icon {
    width: 1.75rem;
    height: 1.75rem;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    border-radius: 999px;
    background: rgba(14, 116, 144, 0.1);
    color: rgba(14, 116, 144, 0.85);
    flex: 0 0 auto;
}

.event-detail__external-link {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    color: var(--color-ocean);
    font-weight: 500;
    text-decoration: none;
    margin-bottom: var(--space-6);
}

.event-detail__external-link:hover {
    text-decoration: underline;
}

.event-detail__actions {
    display: flex;
    gap: var(--space-3);
    flex-wrap: wrap;
    padding-top: var(--space-6);
    border-top: 1px solid var(--color-gray-200);
}

.btn-save-event {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
}

.btn-save-event.saved {
    background: var(--color-ocean);
    border-color: var(--color-ocean);
    color: var(--color-white);
}

.share-buttons {
    margin-left: auto;
}

.back-to-events {
    margin-top: var(--space-8);
    text-align: center;
}


/* ============================================
   Events Page Header
   ============================================ */
.events-header {
    background: linear-gradient(135deg, var(--color-ocean) 0%, var(--color-driftwood) 100%);
    color: var(--color-white);
    padding: var(--space-12) 0;
}

.events-header .region-breadcrumb {
    margin-bottom: var(--space-4);
}

.events-header .region-breadcrumb a {
    color: rgba(255,255,255,0.8);
}

.events-header .region-breadcrumb a:hover {
    color: var(--color-white);
}

.events-header__title {
    font-family: var(--font-display);
    font-size: 2.5rem;
    font-weight: 700;
    margin-bottom: var(--space-2);
}

.events-header__subtitle {
    opacity: 0.9;
}

.events-filters {
    background: var(--color-white);
    border-bottom: 1px solid var(--color-gray-200);
    padding: var(--space-4) 0;
    position: sticky;
    top: 60px;
    z-index: 100;
}

.filter-group {
    margin-bottom: var(--space-3);
}

.filter-group:last-child {
    margin-bottom: 0;
}

.filter-label {
    display: block;
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--color-gray-500);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    margin-bottom: var(--space-2);
}

.area-filters {
    display: flex;
    gap: var(--space-2);
    flex-wrap: wrap;
}

.area-filter {
    display: inline-flex;
    align-items: center;
    gap: var(--space-2);
    padding: var(--space-2) var(--space-3);
    border-radius: var(--radius-full);
    background: var(--color-gray-100);
    color: var(--color-gray-600);
    font-size: 0.8125rem;
    font-weight: 500;
    text-decoration: none;
    cursor: pointer;
    transition: all var(--transition-fast);
    border: 2px solid transparent;
}

.area-filter:hover {
    background: var(--color-gray-200);
    color: var(--color-gray-700);
    text-decoration: none;
}

.area-filter.active {
    background: var(--color-sunset);
    color: var(--color-white);
    border-color: var(--color-sunset);
}


/* ============================================
   Monthly Calendar Grid
   ============================================ */
.events-calendar-section {
    padding: var(--space-4) 0 0;
}

.region-calendar {
    max-width: 420px;
    margin: 0 auto var(--space-6);
    background: var(--color-white);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-sm);
    padding: var(--space-4);
}

.region-calendar__header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: var(--space-3);
}

.region-calendar__month {
    font-family: var(--font-display);
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--color-gray-800);
}

.region-calendar__nav {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 32px;
    height: 32px;
    border-radius: var(--radius-full);
    color: var(--color-gray-600);
    text-decoration: none;
    transition: all var(--transition-fast);
}

.region-calendar__nav:hover {
    background: var(--color-gray-100);
    color: var(--color-ocean);
    text-decoration: none;
}

.region-calendar__table {
    width: 100%;
    border-collapse: collapse;
    table-layout: fixed;
}

.region-calendar__table th {
    text-align: center;
    font-size: 0.6875rem;
    font-weight: 600;
    color: var(--color-gray-400);
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding-bottom: var(--space-2);
}

.region-calendar__day {
    text-align: center;
    padding: var(--space-1);
    vertical-align: middle;
    height: 40px;
}

.region-calendar__day--outside {
    background: none;
}

.region-calendar__day-link {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    margin: 0 auto;
    border-radius: var(--radius-full);
    text-decoration: none;
    color: var(--color-gray-700);
    font-size: 0.8125rem;
    font-weight: 500;
    position: relative;
    transition: all var(--transition-fast);
}

.region-calendar__day-link:hover {
    background: var(--color-gray-100);
    text-decoration: none;
    color: var(--color-ocean);
}

.region-calendar__day-num {
    display: flex;
    align-items: center;
